PROGRAM ST540_KARTONGLINJE
VAR
    steg        : INT := 0;
    tmrRobot    : TON;
    trigReset   : R_TRIG;
    cntCykel    : CTU;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDrift      : BOOL := FALSE;
    xNyKartong  : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. Den har logiken ror inte
   sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

(* Kvittensen borjar en ny kartong. Utan det gar cykellarmet inte att
   kvittera: raknaren star kvar pa sex och larmet slar om direkt igen. *)
IF trigReset.Q THEN
    xNyKartong := TRUE;
END_IF;

(* Kartongen ar 396 x 296 mm invandigt och burken 95 mm i diameter, sa
   4*95 = 380 mm och 3*95 = 285 mm ger tolv burkar i ett lager, 3 x 4.
   Gripdonet tar tva burkar, alltsa sex cykler per kartong. Har sex cykler
   gatt utan att burkraknaren natt tolv har burkarna inte hamnat i
   kartongen. *)
cntCykel(CU := ST540_RB_START, R := xNyKartong, PV := 6);
xNyKartong := FALSE;

(* --- larmkallorna samlas fore domen, sa SYS_ALARM aldrig slapar ett scan
       efter de don den ska stoppa. --- *)

IF cntCykel.CV >= 6 AND ST540_PCK_CNT < 12 AND NOT ST540_RB_START
        AND ST540_ERC_DONE THEN
    xLarm := TRUE;
END_IF;

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Robotcykeln ar 4,0 s. Kommer inte ST540_RB_DONE inom 6,0 s star roboten
   still nagonstans over kartongen med tva glasburkar i gripdonet. *)
tmrRobot(IN := ST540_RB_START, PT := T#6s);
IF tmrRobot.Q THEN
    xLarm := TRUE;
END_IF;

(* Vakuumvakten faller medan roboten bar: burkarna ar pa vag i golvet. *)
IF ST540_RB_START AND NOT ST540_VAC_OK THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET och att nodstopp och
   tryckluft ar tillbaka. Larmet slapper aldrig av sig sjalvt. *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDrift := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDrift THEN
    ST540_CNV_RUN := FALSE;
    ST540_ERC_START := FALSE;
    ST540_RB_START := FALSE;
    ST540_VAC_ON := FALSE;
    ST540_SEA_START := FALSE;
    steg := 0;
ELSE
    ST540_CNV_RUN := TRUE;
    CASE steg OF
        0:
            (* res en kartong och vanta tills den star i lage vid roboten *)
            ST540_SEA_START := FALSE;
            ST540_ERC_START := TRUE;
            IF ST540_ERC_DONE THEN
                ST540_ERC_START := FALSE;
                steg := 1;
            END_IF;
        1:
            (* full kartong gar till forslutaren, annars nytt grepp. Greppet
               far inte kommenderas forran vakuumvakten fallit - star den kvar
               hog ar det forra greppet, inte det nya, som bekraftas. *)
            IF ST540_PCK_CNT >= 12 THEN
                steg := 4;
            ELSIF ST540_PEC_JAR AND NOT ST540_VAC_OK THEN
                ST540_VAC_ON := TRUE;
                steg := 2;
            END_IF;
        2:
            (* roboten far rora sig forst nar greppet haller OCH en rest
               kartong star i lage *)
            IF ST540_VAC_OK AND ST540_ERC_DONE THEN
                ST540_RB_START := TRUE;
                steg := 3;
            END_IF;
        3:
            (* burkarna star i kartongen: forst da slapps vakuumet *)
            IF ST540_RB_DONE THEN
                ST540_RB_START := FALSE;
                ST540_VAC_ON := FALSE;
                steg := 1;
            END_IF;
        4:
            ST540_SEA_START := TRUE;
            IF ST540_SEA_DONE THEN
                ST540_SEA_START := FALSE;
                xNyKartong := TRUE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

